import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.DncwoWA8.js";const i="/projects/ai-skills/diagrams/coordinate-read-only-review.svg",w=JSON.parse('{"title":"Coordinate independent review without writers","description":"","frontmatter":{"title":"Coordinate independent review without writers"},"headers":[],"relativePath":"workflows/coordinate-read-only-review.md","filePath":"workflows/coordinate-read-only-review.md"}'),s={name:"workflows/coordinate-read-only-review.md"};function n(d,e,l,h,c,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="coordinate-independent-review-without-writers" tabindex="-1">Coordinate independent review without writers <a class="header-anchor" href="#coordinate-independent-review-without-writers" aria-label="Permalink to &quot;Coordinate independent review without writers&quot;">​</a></h1><p>This is a focused procedure. For its place in a larger workflow, see <a href="/projects/ai-skills/workflows/supporting-tools.html">Supporting tools and additional workflows</a>.</p><p>You want independent assessment but all changes must stay with the parent.</p><p><strong>Finish with:</strong> Fresh-context read-only findings with evidence and an owner-controlled fix decision.</p><h2 id="read-the-diagram" tabindex="-1">Read the diagram <a class="header-anchor" href="#read-the-diagram" aria-label="Permalink to &quot;Read the diagram&quot;">​</a></h2><p><img src="'+i+'" alt="Coordinate independent review without writers: suggested skill handoffs with approval stops where applicable."></p><p><a href="/projects/ai-skills/diagrams/coordinate-read-only-review.html" class="vp-raw">Open interactive diagram</a> · <a href="/projects/ai-skills/diagrams/coordinate-read-only-review.svg">Download SVG</a> · <a href="/projects/ai-skills/diagram-sources/coordinate-read-only-review.json">Editable candidate</a></p><p>Arrows show this suggested sequence, not declared <code>requires</code> dependencies. Approval arrows are conditional. Declining a gate stops that branch without authorizing its writes. The numbered steps below are the text equivalent of the diagram.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Use a trusted project and follow its instructions. Confirm the requested scope, installed skills, runtime tools, and any required workspace or approval. No additional instruction requirement is recorded for these selected steps.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li><strong>Assign read-only questions.</strong> <a href="/projects/ai-skills/skills/background-agents.html"><code>background-agents</code></a> provides the guidance for this step.</li><li><strong>Review standards + spec.</strong> <a href="/projects/ai-skills/skills/code-review.html"><code>code-review</code></a> provides the guidance for this step.</li><li><strong>Verify + integrate findings.</strong> <a href="/projects/ai-skills/skills/background-agents.html"><code>background-agents</code></a> provides the guidance for this step.</li><li><strong>Owner decides next step.</strong> <a href="/projects/ai-skills/skills/background-agents.html"><code>background-agents</code></a> provides the guidance for this step.</li></ol><h2 id="where-to-stop" tabindex="-1">Where to stop <a class="header-anchor" href="#where-to-stop" aria-label="Permalink to &quot;Where to stop&quot;">​</a></h2><p>Do not silently promote reviewers to writers or substitute another launcher after a delegation failure. Fixing findings is separate from the review.</p><h2 id="optional-branches" tabindex="-1">Optional branches <a class="header-anchor" href="#optional-branches" aria-label="Permalink to &quot;Optional branches&quot;">​</a></h2><ul><li>Choose <a href="/projects/ai-skills/skills/coding-with-rules.html"><code>coding-with-rules</code></a> when code or toolchain work needs the base coding workflow plus rules for its actual languages and extensions.</li></ul><p>Optional branches are not prerequisites or permission to launch another phase. You can omit them or stop at the stated result. See <a href="/projects/ai-skills/reference/relationships.html">relationship types</a> for the distinction.</p>',17)])])}const g=t(s,[["render",n]]);export{w as __pageData,g as default};
